import { Info } from 'lucide-react';

const METRICS_CONFIG = [
  { key: 'accuracy', label: 'Accuracy', desc: 'Proportion de prédictions correctes parmi toutes les prédictions.', color: '#10b981', bg: 'rgba(16,185,129,0.06)', border: 'rgba(16,185,129,0.15)' },
  { key: 'precision', label: 'Precision', desc: 'Proportion de vrais positifs parmi les prédictions positives.', color: '#666CFF', bg: 'rgba(102,108,255,0.06)', border: 'rgba(102,108,255,0.15)' },
  { key: 'recall', label: 'Recall', desc: 'Proportion de vrais positifs détectés parmi tous les positifs réels.', color: '#6366f1', bg: 'rgba(99,102,241,0.06)', border: 'rgba(99,102,241,0.15)' },
  { key: 'f1_score', label: 'F1-Score', desc: 'Moyenne harmonique de precision et recall.', color: '#8b5cf6', bg: 'rgba(139,92,246,0.06)', border: 'rgba(139,92,246,0.15)' },
];

export default function ModelMetricsCard({ metrics, detailed }) {
  if (!metrics) return null;

  const cols = detailed ? 'grid-cols-1 md:grid-cols-4' : 'grid-cols-2 md:grid-cols-4';

  return (
    <div className={`grid ${cols} gap-4`}>
      {METRICS_CONFIG.map((m) => {
        const val = metrics[m.key] ?? 0;
        const pct = (val * 100).toFixed(1);
        return (
          <div key={m.key} className="rounded-xl p-4 relative group" style={{ background: m.bg, border: `1px solid ${m.border}` }}>
            <div className="flex items-center justify-between mb-2">
              <span className="text-xs font-medium text-text-secondary">{m.label}</span>
              <Info size={14} className="text-text-secondary/50 cursor-help" />
            </div>
            <p className="text-2xl font-bold font-mono" style={{ color: m.color }}>{pct}%</p>
            <div className="mt-2 w-full h-1.5 bg-white/50 rounded-full overflow-hidden">
              <div className="h-full rounded-full" style={{ width: `${pct}%`, backgroundColor: m.color }} />
            </div>
            {/* Tooltip */}
            <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-3 py-1.5 rounded-lg bg-gray-900 text-white text-[11px] leading-relaxed whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-10 shadow-lg">
              {m.desc}
            </div>
          </div>
        );
      })}
    </div>
  );
}
