import { ShoppingBag } from 'lucide-react';

export default function ProductPairs({ pairs, products }) {
  if (!pairs || pairs.length === 0) return null;

  const topPairs = [...pairs].sort((a, b) => b.co_occurrence - a.co_occurrence).slice(0, 8);
  const maxOccur = topPairs[0]?.co_occurrence || 1;

  const findName = (id) => {
    const p = products?.find((pr) => pr.id === id);
    return p ? p.name : id;
  };

  return (
    <div className="bg-white shadow-card rounded-xl p-5">
      <div className="flex items-center gap-2 mb-4">
        <ShoppingBag size={20} className="text-primary" />
        <h2 className="text-base font-semibold text-text-primary">Paires de Produits Fréquents</h2>
      </div>
      <div className="flex flex-col gap-3">
        {topPairs.map((pair, i) => {
          const pct = (pair.co_occurrence / maxOccur * 100);
          return (
            <div key={i}>
              <div className="flex items-center justify-between mb-1">
                <span className="text-xs font-medium text-text-primary truncate max-w-[70%]">
                  {findName(pair.product_a)} ↔ {findName(pair.product_b)}
                </span>
                <span className="text-xs font-bold font-mono text-primary">{pair.co_occurrence}</span>
              </div>
              <div className="w-full h-1.5 bg-gray-100 rounded-full overflow-hidden">
                <div className="h-full rounded-full bg-primary" style={{ width: `${pct}%` }} />
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
