import { ShoppingBag, TrendingUp, DollarSign, Package } from 'lucide-react';

export default function BasketStats({ baskets, transactions }) {
  if (!baskets || baskets.length === 0) return null;

  const totalBaskets = baskets.length;
  const avgSize = baskets.reduce((s, b) => s + (b.items?.length || 0), 0) / totalBaskets;
  const avgSpend = baskets.reduce((s, b) => s + (b.total || 0), 0) / totalBaskets;
  const uniqueProducts = new Set();
  baskets.forEach((b) => (b.items || []).forEach((item) => uniqueProducts.add(item.product_id || item.name)));

  const stats = [
    { label: 'Paniers Analysés', value: totalBaskets.toLocaleString('fr-FR'), color: '#666CFF', icon: ShoppingBag },
    { label: 'Taille Moyenne', value: avgSize.toFixed(1) + ' items', color: '#10b981', icon: Package },
    { label: 'Panier Moyen', value: avgSpend.toLocaleString('fr-FR', { minimumFractionDigits: 2 }) + ' MAD', color: '#f59e0b', icon: DollarSign },
    { label: 'Produits Uniques', value: uniqueProducts.size.toLocaleString('fr-FR'), color: '#6366f1', icon: TrendingUp },
  ];

  return (
    <div className="bg-white shadow-card rounded-xl p-5">
      <div className="flex items-center gap-2 mb-4">
        <ShoppingBag size={20} className="text-primary" />
        <h2 className="text-base font-semibold text-text-primary">Statistiques Paniers</h2>
      </div>
      <div className="grid grid-cols-2 gap-3 mb-4">
        {stats.map((s) => {
          const Icon = s.icon;
          return (
            <div key={s.label} className="rounded-xl p-3.5 text-center" style={{ background: 'rgba(102,108,255,0.04)', border: '1px solid rgba(102,108,255,0.1)' }}>
              <Icon size={16} color={s.color} className="mx-auto mb-1" />
              <p className="text-lg font-bold font-mono" style={{ color: s.color }}>{s.value}</p>
              <p className="text-[10px] text-text-secondary">{s.label}</p>
            </div>
          );
        })}
      </div>

      {/* Sample baskets */}
      <h3 className="text-xs font-semibold text-text-secondary uppercase tracking-wider mb-2">Échantillon de Paniers</h3>
      <div className="flex flex-col gap-2">
        {baskets.slice(0, 5).map((b, i) => (
          <div key={i} className="rounded-lg p-2.5 bg-gray-50/50 border border-border-color/50">
            <div className="flex items-center justify-between mb-1">
              <span className="text-xs font-medium text-text-secondary">Panier #{b.basket_id || i + 1}</span>
              <span className="text-[10px] font-bold text-primary">{b.total?.toFixed(2) || '—'} MAD</span>
            </div>
            <div className="flex flex-wrap gap-1">
              {(b.items || []).slice(0, 4).map((item, j) => (
                <span key={j} className="text-[10px] px-1.5 py-0.5 rounded bg-white border border-border-color text-text-secondary">
                  {item.name || item.product_id}
                </span>
              ))}
              {(b.items?.length || 0) > 4 && (
                <span className="text-[10px] px-1.5 py-0.5 rounded bg-white border border-border-color text-text-secondary">
                  +{b.items.length - 4}
                </span>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
