import { Cpu } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';

export default function FeatureImportanceChart({ data }) {
  if (!data || data.length === 0) return null;

  const chartData = [...data].sort((a, b) => b.importance - a.importance).slice(0, 10);

  return (
    <div className="bg-white shadow-card rounded-xl p-5">
      <div className="flex items-center gap-2 mb-4">
        <Cpu size={20} className="text-primary" />
        <h2 className="text-base font-semibold text-text-primary">Importance des Features</h2>
      </div>
      <ResponsiveContainer width="100%" height={320}>
        <BarChart data={chartData} layout="vertical" margin={{ left: 20, right: 20 }}>
          <XAxis type="number" tick={{ fontSize: 11, fill: 'rgba(58,53,65,0.6)' }} />
          <YAxis type="category" dataKey="feature" tick={{ fontSize: 11, fill: 'rgba(58,53,65,0.87)' }} width={140} />
          <Tooltip
            contentStyle={{ borderRadius: 10, border: 'none', boxShadow: '0 2px 10px rgba(76,78,100,0.1)', fontSize: 12 }}
            formatter={(v) => [(v * 100).toFixed(1) + '%', 'Importance']} />
          <Bar dataKey="importance" radius={[0, 6, 6, 0]} fill="#666CFF" maxBarSize={20} />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
}
