import { Info } from 'lucide-react';

export default function ConfusionMatrix({ data }) {
  if (!data) return null;

  const { true_positives: tp, false_positives: fp, true_negatives: tn, false_negatives: fn } = data;
  const total = tp + fp + tn + fn || 1;
  const accuracy = ((tp + tn) / total * 100).toFixed(1);

  const cells = [
    { label: 'Vrai Positif (TP)', value: tp, desc: 'Produits correctement recommandés', color: 'text-emerald-600', bg: 'bg-emerald-50', border: 'border-emerald-200' },
    { label: 'Faux Positif (FP)', value: fp, desc: 'Produits recommandés à tort', color: 'text-red-500', bg: 'bg-red-50', border: 'border-red-200' },
    { label: 'Faux Négatif (FN)', value: fn, desc: 'Produits non recommandés qui auraient dû l\'être', color: 'text-red-500', bg: 'bg-red-50', border: 'border-red-200' },
    { label: 'Vrai Négatif (TN)', value: tn, desc: 'Produits correctement non recommandés', color: 'text-emerald-600', bg: 'bg-emerald-50', border: 'border-emerald-200' },
  ];

  return (
    <div className="bg-white shadow-card rounded-xl p-5">
      <div className="flex items-center gap-2 mb-4">
        <Info size={20} className="text-primary" />
        <h2 className="text-base font-semibold text-text-primary">Matrice de Confusion</h2>
        <span className="ml-auto text-xs font-bold text-emerald-600 bg-emerald-50 px-2.5 py-1 rounded-lg">
          Accuracy globale : {accuracy}%
        </span>
      </div>
      <div className="grid grid-cols-2 gap-3">
        {cells.map((c) => (
          <div key={c.label} className={`rounded-xl p-4 ${c.bg} ${c.border} border`}>
            <p className="text-[11px] font-semibold text-text-secondary mb-1">{c.label}</p>
            <p className={`text-2xl font-bold font-mono ${c.color}`}>{c.value.toLocaleString('fr-FR')}</p>
            <p className="text-[11px] text-text-secondary mt-1">{c.desc}</p>
          </div>
        ))}
      </div>
    </div>
  );
}
