import { useState } from 'react';
import { MessageCircle, CheckCircle, Target, TrendingUp, ChevronUp, ChevronDown, Search } from 'lucide-react';

export default function RecommendationTable({ data }) {
  const [sortField, setSortField] = useState('confidence');
  const [sortDir, setSortDir] = useState('desc');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(0);
  const rowsPerPage = 15;

  const recs = data || [];
  const avgConf = recs.length ? recs.reduce((s, r) => s + r.confidence, 0) / recs.length : 0;
  const highConf = recs.filter((r) => r.confidence >= 0.8).length;

  const filtered = recs
    .filter((r) => !search || r.product_name?.toLowerCase().includes(search.toLowerCase()) || r.user_id?.toLowerCase().includes(search.toLowerCase()))
    .sort((a, b) => {
      const aVal = a[sortField] ?? '';
      const bVal = b[sortField] ?? '';
      if (typeof aVal === 'number') return sortDir === 'asc' ? aVal - bVal : bVal - aVal;
      return sortDir === 'asc' ? String(aVal).localeCompare(String(bVal)) : String(bVal).localeCompare(String(aVal));
    });

  const paged = filtered.slice(page * rowsPerPage, (page + 1) * rowsPerPage);
  const totalPages = Math.ceil(filtered.length / rowsPerPage);

  const columns = [
    { key: 'product_name', label: 'Produit' },
    { key: 'user_id', label: 'Utilisateur' },
    { key: 'category', label: 'Catégorie' },
    { key: 'confidence', label: 'Confiance' },
    { key: 'is_reordered', label: 'Ré-achat' },
  ];

  const KpiIcon = (icon, color) => {
    const Icon = icon;
    return <Icon size={16} color={color} className="mx-auto mb-1.5" />;
  };

  return (
    <div>
      {/* KPI counters */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-5">
        {[
          { label: 'Recommandations', value: recs.length, color: '#666CFF', icon: MessageCircle },
          { label: 'Ré-achats', value: recs.filter((r) => r.is_reordered).length, color: '#10b981', icon: CheckCircle },
          { label: 'Haute Confiance (≥80%)', value: highConf, color: '#6366f1', icon: Target },
          { label: 'Confiance Moyenne', value: `${(avgConf * 100).toFixed(0)}%`, color: '#f59e0b', icon: TrendingUp },
        ].map((s) => {
          const Icon = s.icon;
          return (
            <div key={s.label} className="bg-white shadow-card rounded-xl p-4 text-center">
              <Icon size={16} color={s.color} className="mx-auto mb-1.5" />
              <p className="text-xl font-bold font-mono" style={{ color: s.color }}>{s.value}</p>
              <p className="text-[11px] text-text-secondary mt-0.5">{s.label}</p>
            </div>
          );
        })}
      </div>

      {/* Table */}
      <div className="bg-white shadow-card rounded-xl overflow-hidden">
        <div className="p-3 flex items-center gap-2 border-b border-border-color">
          <div className="relative flex-1 max-w-xs">
            <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-text-secondary" />
            <input type="text" placeholder="Rechercher produit ou utilisateur..."
              value={search} onChange={(e) => { setSearch(e.target.value); setPage(0); }}
              className="w-full h-9 pl-9 pr-3 rounded-lg bg-gray-50 border border-border-color text-sm outline-none focus:border-primary/40 focus:bg-white transition-colors" />
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-border-color bg-gray-50/50">
                {columns.map((col) => (
                  <th key={col.key} className="text-left text-[11px] font-bold text-text-secondary uppercase tracking-wider px-4 py-3 whitespace-nowrap cursor-pointer select-none hover:text-text-primary"
                    onClick={() => {
                      if (sortField === col.key) setSortDir(sortDir === 'asc' ? 'desc' : 'asc');
                      else { setSortField(col.key); setSortDir('desc'); }
                    }}>
                    <span className="flex items-center gap-1">
                      {col.label}
                      {sortField === col.key && (sortDir === 'asc' ? <ChevronUp size={12} /> : <ChevronDown size={12} />)}
                    </span>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {paged.map((r, i) => (
                <tr key={`${r.user_id}-${r.product_name}-${i}`} className="border-b border-border-color/50 hover:bg-gray-50/30">
                  <td className="px-4 py-3 text-sm font-medium">{r.product_name}</td>
                  <td className="px-4 py-3 text-xs text-text-secondary font-mono">{r.user_id}</td>
                  <td className="px-4 py-3">
                    <span className="text-[10px] font-bold px-2 py-0.5 rounded bg-primary-light text-primary">{r.category}</span>
                  </td>
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-2">
                      <div className="w-20 h-1.5 bg-gray-100 rounded-full overflow-hidden">
                        <div className="h-full rounded-full bg-primary" style={{ width: `${r.confidence * 100}%` }} />
                      </div>
                      <span className="text-xs font-bold font-mono">{(r.confidence * 100).toFixed(0)}%</span>
                    </div>
                  </td>
                  <td className="px-4 py-3">
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded ${r.is_reordered ? 'bg-emerald-50 text-emerald-600' : 'bg-gray-50 text-text-secondary'}`}>
                      {r.is_reordered ? 'Oui' : 'Non'}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        {/* Pagination */}
        <div className="flex items-center justify-between px-4 py-3 border-t border-border-color">
          <p className="text-xs text-text-secondary">{filtered.length} résultat{filtered.length > 1 ? 's' : ''}</p>
          <div className="flex items-center gap-1">
            <button onClick={() => setPage(Math.max(0, page - 1))} disabled={page === 0}
              className="px-3 py-1.5 rounded-lg text-xs font-medium text-text-secondary hover:bg-gray-50 disabled:opacity-30 disabled:cursor-not-allowed">Précédent</button>
            <span className="text-xs font-medium px-3">{page + 1} / {totalPages || 1}</span>
            <button onClick={() => setPage(Math.min(totalPages - 1, page + 1))} disabled={page >= totalPages - 1}
              className="px-3 py-1.5 rounded-lg text-xs font-medium text-text-secondary hover:bg-gray-50 disabled:opacity-30 disabled:cursor-not-allowed">Suivant</button>
          </div>
        </div>
      </div>
    </div>
  );
}
