import { TrendingUp } from 'lucide-react';
import { LineChart, Line, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid, Legend } from 'recharts';

export default function RevenueTrendChart({ data }) {
  if (!data || data.length === 0) return null;

  const currentYear = data[data.length - 1]?.year || 2024;
  const prevYear = currentYear - 1;
  const currentTotal = data.filter((d) => d.year === currentYear).reduce((s, d) => s + d.revenue, 0);
  const prevTotal = data.filter((d) => d.year === prevYear).reduce((s, d) => s + d.revenue, 0);
  const growth = prevTotal > 0 ? ((currentTotal - prevTotal) / prevTotal * 100) : 0;

  return (
    <div className="bg-white shadow-card rounded-xl p-5">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <TrendingUp size={20} className="text-primary" />
          <h2 className="text-base font-semibold text-text-primary">Évolution du Revenu</h2>
        </div>
        <span className={`text-xs font-bold px-2.5 py-1 rounded-lg ${growth >= 0 ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-500'}`}>
          {growth >= 0 ? '+' : ''}{growth.toFixed(1)}% vs N-1
        </span>
      </div>
      <ResponsiveContainer width="100%" height={300}>
        <LineChart data={data} margin={{ left: 10, right: 10 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="rgba(58,53,65,0.06)" />
          <XAxis dataKey="month" tick={{ fontSize: 11, fill: 'rgba(58,53,65,0.6)' }} />
          <YAxis tickFormatter={(v) => `${(v / 1000).toFixed(0)}k`} tick={{ fontSize: 11, fill: 'rgba(58,53,65,0.6)' }} />
          <Tooltip
            contentStyle={{ borderRadius: 10, border: 'none', boxShadow: '0 2px 10px rgba(76,78,100,0.1)', fontSize: 12 }}
            formatter={(v) => [`${v.toLocaleString('fr-FR')} MAD`, 'Revenu']} />
          <Legend />
          {[...new Set(data.map((d) => d.year))].map((year, i) => (
            <Line key={year} type="monotone" dataKey="revenue" data={data.filter((d) => d.year === year)}
              name={`${year}`} stroke={i === 0 ? '#666CFF' : '#A8AAFF'} strokeWidth={2} dot={false} activeDot={{ r: 5 }} />
          ))}
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
}
